-- Mantenimiento de Plaza Hudson y Plaza GM 202 (control de Barby, 2026), del Excel "Controles de pago Hudson y GM202".
-- Cada local = unidad tipo local con su cuota de mantenimiento; cada mes pagado = un pago (notas = comentario de la celda).
-- La fecha de pago sale del comentario cuando lo dice; si no, el día 1 del mes. No duplica si se vuelve a correr (legacy_id).
with locales(plaza, slug, num, ocupante, cuota) as (values
('Plaza Hudson','hudson',1,'Cesar Cadena',3240.0),('Plaza Hudson','hudson',2,'Susana Gonzalez',1600.0),('Plaza Hudson','hudson',3,'Rosana Tafich',1600.0),('Plaza Hudson','hudson',4,'Pedro Elizalde',1600.0),('Plaza Hudson','hudson',5,'Margarita Trueba',1800.0),('Plaza Hudson','hudson',6,'Cesar Cadena',3240.0),('Plaza Hudson','hudson',7,'Enrique Pedroza',1600.0),('Plaza Hudson','hudson',8,'Ramiro Johnson',1600.0),('Plaza Hudson','hudson',9,'Mauricio Marcos',1600.0),('Plaza Hudson','hudson',10,'Mauricio Marcos',1600.0),('Plaza Hudson','hudson',11,'Estefania Medellin',5000.0),('Plaza GM 202','gm202',1,'Enrique Nuñez',3000.0),('Plaza GM 202','gm202',2,'Maria Elena Perez',1856.0),('Plaza GM 202','gm202',3,'Rosana Tafich',1856.0),('Plaza GM 202','gm202',4,'Rosana Tafich',1856.0),('Plaza GM 202','gm202',5,'Inmobiliaria Kabla',1600.0),('Plaza GM 202','gm202',6,'Martha',3000.0),('Plaza GM 202','gm202',7,'Ramiro Johnson',1600.0),('Plaza GM 202','gm202',8,'Ramiro Johnson',1600.0),('Plaza GM 202','gm202',9,'Inmobiliaria Kabla',1856.0),('Plaza GM 202','gm202',10,'Inmobiliaria Kabla',1856.0),('Plaza GM 202','gm202',11,'Miguel Medellin',5000.0)
), nuevas as (
  insert into app.unidades (org_id, centro_id, identificador, tipo, ocupante, activo, legacy_id)
  select c.org_id, c.id, l.num::text, 'local', l.ocupante, true, 'barby:' || l.slug || ':' || l.num
  from locales l join app.centros c on c.nombre = l.plaza
  where not exists (select 1 from app.unidades u where u.legacy_id = 'barby:' || l.slug || ':' || l.num)
  returning id, org_id, legacy_id
)
insert into app.cuotas (org_id, unidad_id, concepto, monto, activo, en_padron)
select n.org_id, n.id, 'mantenimiento', l.cuota, true, true
from nuevas n join locales l on n.legacy_id = 'barby:' || l.slug || ':' || l.num;

