insert into app.pagos (org_id, empresa_id, centro_id, unidad_id, concepto, periodo, monto, fecha, notas, capturado_por, legacy_id)
select u.org_id, c.empresa_id, u.centro_id, u.id, 'mantenimiento', make_date(2026, p.mes, 1), p.monto, p.fecha::date,
       'Importado del control de Barby' || coalesce(' · ' || p.nota, ''), 'Bárbara (Excel)', 'barby:' || p.slug || ':' || p.num || ':2026-' || lpad(p.mes::text, 2, '0')
from pagos p
join app.unidades u on u.legacy_id = 'barby:' || p.slug || ':' || p.num
join app.centros c on c.id = u.centro_id
where not exists (select 1 from app.pagos x where x.legacy_id = 'barby:' || p.slug || ':' || p.num || ':2026-' || lpad(p.mes::text, 2, '0'));
